export const LOOKUP_LIMITS = Object.freeze({ queryMaxChars: 80, maxLimit: 61, defaultLimit: 10, defaultListingLimit: 20 });
export const LOOKUP_CHAINS = Object.freeze(["ethereum", "base", "eip155:1", "eip155:8453"]);
export const LOOKUP_KINDS = Object.freeze(["protocol", "brief", "all"]);
export const LOOKUP_TOTALS = Object.freeze({
  protocols: LOOKUP_CATALOG.filter((x) => x.kind === "protocol").length,
  briefs: LOOKUP_CATALOG.filter((x) => x.kind === "brief").length,
  easAttestedProtocols: LOOKUP_CATALOG.filter((x) => x.kind === "protocol" && x.easAttested === true).length,
  rpcObservedProtocols: LOOKUP_CATALOG.filter((x) => x.kind === "protocol" && x.evidenceBasis === "rpc_observed").length,
  items: LOOKUP_CATALOG.length,
});
const LOOKUP_CHAIN_OF = { ethereum: "ethereum", base: "base", "eip155:1": "ethereum", "eip155:8453": "base" };
// C0 / C1 controls, zero-width, line / paragraph separators, bidi embeddings and isolates, BOM: stripped from the query.
const lookupHex4 = (n) => n.toString(16).padStart(4, "0");
const LOOKUP_STRIP = new RegExp("[" + [[0x00, 0x1f], [0x7f, 0x9f], [0x200b, 0x200f], [0x2028, 0x202e], [0x2060, 0x2069], [0xfeff, 0xfeff]]
  .map(([a, b]) => "\\u" + lookupHex4(a) + "-\\u" + lookupHex4(b)).join("") + "]", "g");
const LOOKUP_NOTE = "easAttested protocols are Base-EAS-anchored records that compare on-chain state with the protocol's documentation. "
  + "rpc_observed protocols pin the on-chain control plane over archive JSON-RPC and do not assess the documentation "
  + "(documentationComparison: not_assessed). Briefs are block-pinned verification briefs. preflightArgs re-read the contract live.";
const LOOKUP_NEXT = "Pass a result's preflightArgs ({chain, address}) to pacta_check_preflight (or pacta_scan_control_plane) for a live check.";
const lookupIndex = LOOKUP_CATALOG.map((x) => {
  const lc = (s) => (typeof s === "string" ? s.toLowerCase() : "");
  const name = lc(x.name), tokens = x.tokens.map(lc);
  const addrs = [x.primaryContract, x.controllerAddress, ...(x.surfaces || []).map((s) => s.targetContract)].filter(Boolean).map(lc);
  const words = name.split(/[^a-z0-9+.]+/).filter(Boolean);
  const hay = [x.slug, name, ...tokens, lc(x.category), lc(x.targetLabel), lc(x.venue), ...(x.surfaces || []).flatMap((s) => [lc(s.surface), lc(s.targetLabel)]), ...addrs].join(" ");
  const highlight = x.kind === "brief" ? 2 : (x.classification === "parameter_delta" || (x.surfaces || []).some((s) => s.classification === "parameter_delta")) ? 1 : 3;
  return { item: x, name, tokens, addrs, words, hay, highlight };
});

/** Validate raw inputs. -> {ok: true, query, chain, kind, limit} | {ok: false, error: "invalid_input", detail}. */
export function parseLookupInput(raw = {}) {
  const bad = (detail) => ({ ok: false, error: "invalid_input", detail });
  const r = raw && typeof raw === "object" ? raw : {};
  let query = "";
  if (r.query !== undefined && r.query !== null) {
    if (typeof r.query !== "string") return bad("query must be a string (a protocol name, token symbol, slug or 0x address)");
    query = r.query.replace(LOOKUP_STRIP, "").trim();
    if (query.length > LOOKUP_LIMITS.queryMaxChars) return bad(`query must be at most ${LOOKUP_LIMITS.queryMaxChars} characters`);
  }
  let chain = null;
  if (r.chain !== undefined && r.chain !== null && r.chain !== "") {
    const c = typeof r.chain === "string" ? r.chain.trim().toLowerCase() : "";
    if (!Object.prototype.hasOwnProperty.call(LOOKUP_CHAIN_OF, c)) return bad("chain must be one of " + LOOKUP_CHAINS.join(", "));
    chain = LOOKUP_CHAIN_OF[c];
  }
  let kind = "all";
  if (r.kind !== undefined && r.kind !== null && r.kind !== "") {
    const k = typeof r.kind === "string" ? r.kind.trim().toLowerCase() : "";
    if (!LOOKUP_KINDS.includes(k)) return bad("kind must be one of " + LOOKUP_KINDS.join(", "));
    kind = k;
  }
  const listing = query === "" || query === "*";
  let limit = listing ? LOOKUP_LIMITS.defaultListingLimit : LOOKUP_LIMITS.defaultLimit;
  if (r.limit !== undefined && r.limit !== null && r.limit !== "") {
    const n = typeof r.limit === "number" ? r.limit : typeof r.limit === "string" && /^[0-9]{1,3}$/.test(r.limit.trim()) ? Number(r.limit.trim()) : NaN;
    if (!Number.isSafeInteger(n) || n < 1 || n > LOOKUP_LIMITS.maxLimit) return bad(`limit must be an integer from 1 to ${LOOKUP_LIMITS.maxLimit}`);
    limit = n;
  }
  return { ok: true, query: listing ? "" : query, chain, kind, limit };
}

/** Rank one catalog entry for a lower-cased query: 1 exact, 2 prefix, 3 substring / every term, 0 no match. */
function lookupRank(e, q) {
  const x = e.item;
  if (q === x.slug || e.tokens.includes(q) || e.name === q || (/^0x[0-9a-f]{40}$/.test(q) && e.addrs.includes(q))) return 1;
  if (x.slug.startsWith(q) || e.name.startsWith(q) || e.words.some((w) => w.startsWith(q)) || e.tokens.some((t) => t.startsWith(q))) return 2;
  const terms = q.split(/[\s,]+/).filter(Boolean);
  return terms.length && terms.every((t) => e.hay.includes(t)) ? 3 : 0;
}
const LOOKUP_MATCH = ["listing", "exact", "prefix", "substring"];

/** Search the catalog. -> the pacta.protocol_lookup.v1 result, or {ok: false, error, detail} for invalid input. */
export function lookupProtocols(raw = {}) {
  const p = parseLookupInput(raw);
  if (!p.ok) return p;
  const q = p.query.toLowerCase();
  const pool = lookupIndex.filter((e) => (!p.chain || e.item.chain === p.chain) && (p.kind === "all" || e.item.kind === p.kind));
  const scored = q === ""
    ? pool.map((e) => ({ e, rank: e.highlight, match: 0 }))
    : pool.map((e) => { const r = lookupRank(e, q); return { e, rank: r, match: r }; }).filter((s) => s.rank > 0);
  scored.sort((a, b) => a.rank - b.rank || (a.e.item.kind === b.e.item.kind ? 0 : a.e.item.kind === "protocol" ? -1 : 1)
    || (a.e.item.slug < b.e.item.slug ? -1 : a.e.item.slug > b.e.item.slug ? 1 : 0));
  const results = scored.slice(0, p.limit).map((s) => ({ ...s.e.item, match: LOOKUP_MATCH[s.match] }));
  const out = { schema: LOOKUP_SCHEMA, query: p.query, filters: { chain: p.chain, kind: p.kind, limit: p.limit },
    totalCatalog: { protocols: LOOKUP_TOTALS.protocols, briefs: LOOKUP_TOTALS.briefs, easAttestedProtocols: LOOKUP_TOTALS.easAttestedProtocols,
      rpcObservedProtocols: LOOKUP_TOTALS.rpcObservedProtocols },
    totalMatches: scored.length, count: results.length, results, catalog: LOOKUP_CATALOG_URL, nextStep: LOOKUP_NEXT, note: LOOKUP_NOTE };
  if (!results.length) {
    out.hint = "No match. Call again with an empty query to list what Pacta tracks, or pass a known 0x contract address straight to pacta_check_preflight.";
  }
  return out;
}
// ---- control-plane status badges (GET /v1/badges/<slug>.svg on the worker, docs/badges/<slug>.svg on the site).
// Three truthful tiers per protocol page: "aligned" (every record an EAS-attested aligned_baseline), "parameter_delta"
// (EAS-attested, at least one record differs from the documentation), "rpc_observed" (RPC-pinned only, documentation not
// assessed; never implies an EAS attestation). Byte-identical to tools/build_lookup.py badge_svg() (the site build checks).
export const BADGE_TIERS = Object.freeze({
  aligned: Object.freeze({ label: "Aligned · Base EAS", color: "#047857" }),
  parameter_delta: Object.freeze({ label: "Parameter Delta", color: "#b45309" }),
  rpc_observed: Object.freeze({ label: "RPC-Observed", color: "#475569" }),
});
export const BADGE_TITLE = "Pacta Control Plane";
const BADGE_SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
export function badgeTier(item) {
  if (!item || item.kind !== "protocol") return null;
  if (item.evidenceBasis === "rpc_observed") return "rpc_observed";
  return item.classification === "aligned_baseline" ? "aligned" : "parameter_delta";
}
/** Deterministic flat shield for a published protocol slug; null for anything else. */
export function badgeSvg(slug) {
  if (typeof slug !== "string" || slug.length > 80 || !BADGE_SLUG_RE.test(slug)) return null;
  const item = LOOKUP_CATALOG.find((x) => x.kind === "protocol" && x.slug === slug);
  const tier = badgeTier(item);
  if (!tier) return null;
  const t = BADGE_TIERS[tier], left = BADGE_TITLE, right = t.label;
  const lw = left.length * 7 + 12, rw = right.length * 7 + 12, w = lw + rw;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="20" role="img" aria-label="${left}: ${right}">`
    + `<title>${left}: ${right} (${slug})</title>`
    + `<clipPath id="r"><rect width="${w}" height="20" rx="3" fill="#fff"/></clipPath>`
    + `<g clip-path="url(#r)"><rect width="${lw}" height="20" fill="#1f2937"/><rect x="${lw}" width="${rw}" height="20" fill="${t.color}"/></g>`
    + `<g fill="#fff" text-anchor="middle" font-family="Verdana,DejaVu Sans,Geneva,sans-serif" font-size="11">`
    + `<text x="${lw / 2}" y="14">${left}</text><text x="${lw + rw / 2}" y="14">${right}</text></g></svg>\n`;
}
// ---- LOOKUP-END
